with lines as (select id, log_ts, level, latency_ms, status_code, attr_key, attr_value from app_logs lateral view explode(context) x as attr_key, attr_value) select id, log_ts, level, latency_ms, status_code, attr_key, attr_value, lead(status_code, 2) over (partition by attr_key order by log_ts, id, attr_key) next_status_code, sum(status_code) over w_grp running_status_code, lead(latency_ms, 1) over (partition by level order by log_ts, id, attr_key) next_latency_ms, last_value(latency_ms, true) over (partition by attr_key, level order by latency_ms, id, attr_key rows between unbounded preceding and current row) last_known_latency_ms, percent_rank() over (partition by level order by status_code desc) status_code_percent_rank from lines window w_grp as (partition by attr_key order by status_code, id, attr_key rows between unbounded preceding and current row);
